          {notificationsOpen && <div className="panel-shadow absolute right-0 top-9 z-50 w-[320px] overflow-hidden rounded-xl border border-[#d7e0e8] bg-white"><div className="flex items-center justify-between border-b border-[#e1e7ed] px-4 py-3"><b className="text-sm">Notifications</b><span className="text-[11px] text-[#789]">3 updates</span></div>{notifications.map((n) => <div key={n.text} className="border-b border-[#edf0f3] px-4 py-3"><div className="flex justify-between"><span className={`rounded px-1.5 py-0.5 text-[10px] font-bold ${n.tone === 'red' ? 'bg-[#ffe0db] text-[#9a453c]' : n.tone === 'blue' ? 'bg-[#e3effa] text-[#356686]' : 'bg-[#e9eef2] text-[#617384]'}`}>{n.label}</span><span className="text-[10px] text-[#8a9aa8]">{n.time}</span></div><p className="mt-1.5 text-xs leading-4 text-[#4c5f70]">{n.text}</p></div>)}<button onClick={() => setNotificationsOpen(false)} className="w-full py-2.5 text-xs font-bold text-[#12698c] hover:bg-[#f2f7f8]" data-testid="button-close-notifications">Mark all as read</button></div>}
