function SectionHeading({ eyebrow, title, action, className }: { eyebrow?: string; title: string; action?: ReactNode; className?: string }) {
  return <div className={`${className ?? 'mb-4'} flex items-end justify-between gap-3`}><div>{eyebrow && <div className="tiny-label mb-1">{eyebrow}</div>}<h2 className="text-[16px] font-bold tracking-[-.02em] text-[#203a52]">{title}</h2></div>{action}</div>;
}
function CourseCard({ course, onEnroll, catalog = false }: { course: Course; onEnroll?: (id: string) => void; catalog?: boolean }) {
  const [, setLocation] = useLocation();
  return <div className={`panel-shadow group overflow-hidden rounded-xl border border-[#d6e0e7] bg-white transition-transform hover:-translate-y-0.5 ${catalog ? '' : ''}`} data-testid={`card-course-${course.id}`}>
    <button onClick={() => setLocation(`/courses/${course.id}`)} className="block w-full text-left" data-testid={`button-open-course-${course.id}`}>
      <div className="relative h-[94px] overflow-hidden" style={{ background: `linear-gradient(135deg, ${course.color} 0%, #d9e8ed 100%)` }}><div className="absolute -right-5 -top-9 h-36 w-36 rounded-full border-[18px] border-white/20" /><div className="absolute bottom-3 left-4 max-w-[80%] text-[11px] font-bold uppercase tracking-[.1em] text-white/85">{course.category}</div>{course.progress > 0 && <span className="absolute right-2 top-2 rounded-full bg-[#c6efed] px-2 py-1 text-[10px] font-bold text-[#1e6b73]">In progress</span>}</div>
      <div className={catalog ? 'p-3.5' : 'p-2.5'}><h3 className="truncate text-[14px] font-bold text-[#21384d]">{course.title}</h3><p className="mt-1 text-[11px] text-[#70808e]">{course.trainer}</p>
        {catalog && <div className="mt-3 flex gap-1.5">{course.tags.map(tag => <span key={tag} className="rounded bg-[#edf4f6] px-2 py-1 text-[10px] font-semibold text-[#2c7077]">{tag}</span>)}</div>}
        {!catalog && <><div className="mt-2 flex justify-between text-[10px] font-semibold text-[#687b8b]"><span>Progress</span><span>{course.progress}%</span></div><div className="mt-1 h-1.5 rounded-full bg-[#e6eaed]"><div className="h-full rounded-full bg-[#137c7e]" style={{ width: `${course.progress}%` }} /></div></>}
      </div>
    </button>
    {catalog && <div className="flex items-center justify-between border-t border-[#edf1f3] px-3.5 py-3"><span className="text-[11px] text-[#71818e]"><Clock3 size={12} className="mr-1 inline" />{course.duration} · {course.level}</span><button onClick={() => onEnroll?.(course.id)} disabled={course.progress > 0} data-testid={`button-enroll-${course.id}`} className={`rounded-md px-3 py-1.5 text-[11px] font-bold ${course.progress > 0 ? 'bg-[#e4f1ee] text-[#25726b]' : 'bg-[#075fa6] text-white hover:bg-[#064f8b]'}`}>{course.progress > 0 ? 'Enrolled' : 'Enroll'}</button></div>}
  </div>;
}

