function Catalog() {
  const [query, setQuery] = useState(''); const [category, setCategory] = useState('All'); const [level, setLevel] = useState('All'); const [enrolled, setEnrolled] = useState<Record<string, boolean>>({ synoptic: true });
  const { toast } = useToast();
  const filtered = useMemo(() => courses.filter(c => (!query || `${c.title} ${c.trainer} ${c.tags.join(' ')}`.toLowerCase().includes(query.toLowerCase())) && (category === 'All' || c.category === category) && (level === 'All' || c.level === level)), [query, category, level]);
  const enroll = (id: string) => { setEnrolled(s => ({ ...s, [id]: true })); toast({ title: 'Course added to your plan', description: 'You can start learning from My Courses.' }); };
  return <div className="mx-auto max-w-[1220px] p-5 md:p-8"><div className="mb-7"><div className="tiny-label mb-2">Learning library</div><h1 className="text-[28px] font-bold tracking-[-.04em] text-[#124b78]">Course catalog</h1><p className="mt-1 text-sm text-[#667887]">Build the capabilities your next assignment needs.</p></div><div className="mb-6 flex flex-col gap-3 rounded-xl border border-[#d6e0e7] bg-white p-3 panel-shadow lg:flex-row"><div className="relative flex-1"><Search size={17} className="absolute left-3 top-2.5 text-[#7e909d]" /><input value={query} onChange={e => setQuery(e.target.value)} data-testid="input-course-search" placeholder="Search courses, trainers or topics" className="h-9 w-full rounded-lg border border-[#d7e1e7] bg-[#f9fbfc] pl-9 pr-3 text-xs outline-none focus:border-[#6eafb1]" /></div><div className="flex flex-wrap items-center gap-2"><SlidersHorizontal size={15} className="text-[#6f818f]" />{['All','Forecasting','Data Analysis','Climate','Communication'].map(x => <button key={x} onClick={() => setCategory(x)} data-testid={`button-filter-category-${x.toLowerCase().replace(' ','-')}`} className={`rounded-full px-3 py-1.5 text-[11px] font-bold ${category === x ? 'bg-[#16698a] text-white' : 'bg-[#eef3f5] text-[#617482]'}`}>{x}</button>)}<select value={level} onChange={e => setLevel(e.target.value)} data-testid="select-level" className="rounded-full border border-[#d4dfe6] bg-white px-3 py-1.5 text-[11px] font-bold text-[#617482] outline-none"><option>All</option><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></div></div><div className="mb-4 flex items-center justify-between"><span className="text-xs text-[#748594]">{filtered.length} learning pathways</span><span className="text-xs font-bold text-[#1d607b]">Recommended for Ananya</span></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{filtered.map(c => <CourseCard key={c.id} course={{ ...c, progress: enrolled[c.id] ? Math.max(c.progress, 1) : c.progress }} catalog onEnroll={enroll} />)}</div>{filtered.length === 0 && <div className="rounded-xl border border-dashed border-[#afc3cd] bg-[#f8fbfc] p-12 text-center"><Search className="mx-auto text-[#5d9aa0]" /><p className="mt-3 text-sm font-bold text-[#35536a]">No courses match those filters</p><button onClick={() => { setQuery(''); setCategory('All'); setLevel('All'); }} data-testid="button-clear-filters" className="mt-3 text-xs font-bold text-[#176e83] underline">Clear filters</button></div>}</div>;
}

function CourseDetail() {
  const { id } = useParams<{ id: string }>(); const course = courses.find(c => c.id === id) ?? courses[0]; const [tab, setTab] = useState('Overview'); const [viewer, setViewer] = useState<string | null>(null); const [rating, setRating] = useState(0); const [comment, setComment] = useState(''); const { toast } = useToast(); const [, setLocation] = useLocation();
  const enrolled = course.progress > 0;
  return <div className="mx-auto max-w-[1120px] p-5 md:p-8"><Link href="/catalog" data-testid="link-back-catalog" className="mb-5 inline-flex items-center gap-2 text-xs font-bold text-[#557284] hover:text-[#125d78]"><ArrowLeft size={14} /> Course catalog</Link><div className="overflow-hidden rounded-xl border border-[#d6e0e7] bg-white panel-shadow"><div className="relative min-h-[205px] p-6 md:p-9" style={{ background: `linear-gradient(115deg, ${course.color}, #d7e6e9)` }}><div className="max-w-[610px] text-white"><span className="rounded bg-white/20 px-2 py-1 text-[10px] font-bold uppercase tracking-wider">{course.category} · {course.level}</span><h1 className="mt-4 text-[29px] font-bold leading-tight tracking-[-.04em]">{course.title}</h1><p className="mt-2 max-w-[520px] text-sm text-white/85">{course.description}</p><div className="mt-5 flex flex-wrap gap-4 text-xs font-semibold text-white/85"><span><UserRound size={14} className="mr-1 inline" />{course.trainer}</span><span><Clock3 size={14} className="mr-1 inline" />{course.duration}</span><span><Award size={14} className="mr-1 inline" />Certificate eligible</span></div></div></div><div className="flex gap-1 overflow-x-auto border-b border-[#e4eaee] px-4 pt-2 md:px-7">{['Overview','Lectures / Materials','Assessment','Feedback'].map(t => <button onClick={() => setTab(t)} key={t} data-testid={`button-tab-${t.split(' ')[0].toLowerCase()}`} className={`whitespace-nowrap border-b-2 px-3 py-3 text-xs font-bold ${tab === t ? 'border-[#177c80] text-[#177278]' : 'border-transparent text-[#758594]'}`}>{t}</button>)}</div><div className="p-5 md:p-7">{tab === 'Overview' && <div className="grid gap-8 md:grid-cols-[1.35fr_1fr]"><div><SectionHeading eyebrow="About this pathway" title="What you will learn" /><p className="text-sm leading-6 text-[#5e7181]">{course.description} You will work through operational examples and leave with a practical decision framework for your next forecast discussion.</p><div className="mt-7 grid gap-3 sm:grid-cols-2">{['Interpret synoptic patterns with confidence','Apply structured quality checks','Communicate uncertainty clearly','Connect evidence to an operational decision'].map((x, i) => <div key={x} className="flex gap-2 text-xs font-medium text-[#425a6c]"><CheckCircle2 size={16} className="shrink-0 text-[#208288]" />{x}</div>)}</div></div><div className="rounded-xl bg-[#f0f7f7] p-5"><div className="tiny-label mb-3">Your progress</div><div className="flex items-end justify-between"><span className="text-3xl font-bold text-[#195e6d]">{course.progress}%</span><span className="text-xs text-[#607986]">of pathway complete</span></div><div className="mt-3 h-2 rounded-full bg-[#d9e7e7]"><div className="h-full rounded-full bg-[#157c7f]" style={{ width: `${course.progress}%` }} /></div><button onClick={() => setTab('Lectures / Materials')} data-testid="button-continue-course" className="mt-5 w-full rounded-lg bg-[#075fa6] py-2.5 text-xs font-bold text-white">{course.progress ? 'Continue learning' : 'Start pathway'}</button></div></div>}{tab === 'Lectures / Materials' && <div className="max-w-2xl"><SectionHeading eyebrow="Course materials" title="Lectures and resources" /><div className="space-y-2">{['Foundations and framing','Reading the operational chart','Case study: a fast-moving system','Knowledge check and reflection'].map((x, i) => <button onClick={() => setViewer(x)} key={x} data-testid={`button-lecture-${i}`} className="flex w-full items-center gap-3 rounded-lg border border-[#dae4e9] bg-[#fbfcfd] p-3 text-left hover:border-[#74aeb0]"><div className="grid h-9 w-9 place-items-center rounded-lg bg-[#e2f0f1] text-[#18717a]">{i === 1 ? <Play size={16} /> : <FileText size={16} />}</div><div className="flex-1"><div className="text-xs font-bold text-[#30495e]">{x}</div><div className="mt-1 text-[10px] text-[#7c8c99]">{i === 1 ? 'Video lecture · 18 min' : 'Reading material · PDF'}</div></div><ChevronRight size={15} className="text-[#81929f]" /></button>)}</div></div>}{tab === 'Assessment' && <div className="max-w-xl rounded-xl border border-[#d6e0e7] bg-[#f8fbfc] p-6"><div className="grid h-11 w-11 place-items-center rounded-xl bg-[#d8eff0] text-[#126c76]"><Target size={22} /></div><h2 className="mt-4 text-xl font-bold text-[#294359]">Pathway assessment</h2><p className="mt-2 text-sm leading-6 text-[#667a89]">Test your understanding across four applied questions. Your results map to the competency profile.</p><div className="mt-5 flex gap-5 text-xs text-[#6a7d8a]"><span>12 questions</span><span>20 minutes</span><span>Certificate eligible</span></div><button onClick={() => setLocation(`/courses/${course.id}/assessment`)} disabled={!enrolled} data-testid="button-assessment-start" className="mt-6 rounded-lg bg-[#075fa6] px-5 py-2.5 text-xs font-bold text-white disabled:cursor-not-allowed disabled:bg-[#b7c7d0]">{enrolled ? 'Take assessment' : 'Enroll to unlock'}</button></div>}{tab === 'Feedback' && <div className="grid gap-8 md:grid-cols-[1fr_1fr]"><div><SectionHeading eyebrow="Share your experience" title="How was this pathway?" /><div className="flex gap-2">{[1,2,3,4,5].map(n => <button key={n} onClick={() => setRating(n)} data-testid={`button-rating-${n}`} className={`text-2xl ${n <= rating ? 'text-[#d59b3e]' : 'text-[#c7d2d7]'}`}>★</button>)}</div><textarea value={comment} onChange={e => setComment(e.target.value)} data-testid="textarea-feedback" placeholder="What was most useful for your work?" className="mt-4 h-28 w-full resize-none rounded-lg border border-[#d5e0e6] p-3 text-sm outline-none focus:border-[#6caeb0]" /><button onClick={() => { toast({ title: 'Feedback submitted', description: 'Thank you for helping us improve the learning experience.' }); setComment(''); setRating(0); }} data-testid="button-submit-feedback" className="mt-3 rounded-lg bg-[#075fa6] px-4 py-2.5 text-xs font-bold text-white">Submit feedback</button></div><div className="rounded-xl bg-[#f2f7f8] p-5"><div className="tiny-label mb-3">Learner notes</div><p className="text-sm leading-6 text-[#5e7181]">“The case study helped me connect the chart patterns to the briefing language we use during morning duty.”</p><div className="mt-3 text-xs font-bold text-[#2f6470]">— R. Kapoor, Regional Centre</div></div></div>}</div></div>{viewer && <div className="fixed inset-0 z-50 grid place-items-center bg-[#19364c]/40 p-5" onClick={() => setViewer(null)}><div onClick={e => e.stopPropagation()} className="w-full max-w-2xl rounded-xl bg-white p-5 panel-shadow"><div className="flex items-center justify-between"><div><div className="tiny-label">Previewing material</div><h2 className="mt-1 text-lg font-bold text-[#27445a]">{viewer}</h2></div><button onClick={() => setViewer(null)} data-testid="button-close-viewer"><X size={19} /></button></div><div className="mt-5 grid h-56 place-items-center rounded-lg bg-[#eaf1f3] text-center"><div><div className="mx-auto grid h-12 w-12 place-items-center rounded-full bg-[#c9e4e5] text-[#176e77]"><Play size={21} /></div><p className="mt-3 text-sm font-bold text-[#4f6b7b]">Learning preview</p><p className="mt-1 text-xs text-[#7e909b]">This prototype opens the embedded lesson viewer here.</p></div></div></div></div>}</div>;
}

function Profile() {
  const [editing, setEditing] = useState(false); const [name, setName] = useState('Ananya Sharma'); const [role, setRole] = useState('Scientific Assistant · Regional Centre, Pune'); const [preview, setPreview] = useState(false); const { toast } = useToast();
  return <div className="mx-auto max-w-[1100px] p-5 md:p-8"><div className="mb-7 flex items-end justify-between"><div><div className="tiny-label mb-2">Trainee record</div><h1 className="text-[28px] font-bold tracking-[-.04em] text-[#124b78]">My profile</h1><p className="mt-1 text-sm text-[#667887]">Keep your professional profile current for competency matching.</p></div><button onClick={() => { if (editing) toast({ title: 'Profile saved', description: 'Your trainee record has been updated.' }); setEditing(!editing); }} data-testid="button-edit-profile" className="flex items-center gap-2 rounded-lg border border-[#6ea8af] px-4 py-2.5 text-xs font-bold text-[#236c78] hover:bg-[#eff8f8]">{editing ? <Check size={14} /> : <Pencil size={14} />}{editing ? 'Save changes' : 'Edit profile'}</button></div><div className="grid gap-5 lg:grid-cols-[1.25fr_1fr]"><div className="space-y-5"><section className="rounded-xl border border-[#d6e0e7] bg-white p-5 panel-shadow"><div className="flex items-center gap-4 border-b border-[#e6ecef] pb-5"><div className="grid h-16 w-16 place-items-center rounded-full bg-[#d8ecec] text-lg font-bold text-[#196571]">AS</div><div><h2 className="text-xl font-bold text-[#294359]">{name}</h2><p className="text-xs text-[#718391]">{role}</p><span className="mt-2 inline-block rounded bg-[#e7f2f4] px-2 py-1 text-[10px] font-bold text-[#28717c]">Trainee · Active</span></div></div><div className="mt-5 grid gap-4 sm:grid-cols-2"><Field label="Full name" value={name} editing={editing} onChange={setName} testId="input-profile-name" /><Field label="Work email" value="ananya.sharma@imd.gov.in" editing={editing} testId="input-profile-email" /><Field label="Current assignment" value={role} editing={editing} onChange={setRole} testId="input-profile-role" /><Field label="Regional centre" value="Pune, Maharashtra" editing={editing} testId="input-profile-region" /></div></section><section className="rounded-xl border border-[#d6e0e7] bg-white p-5 panel-shadow"><SectionHeading title="Skills and qualifications" /><div className="mb-4 flex flex-wrap gap-2">{['Forecasting','Data Analysis','Climatology','Public Communication','Python','GIS'].map(x => <span key={x} className="rounded-full border border-[#b9d5d7] bg-[#eff8f8] px-3 py-1.5 text-xs font-semibold text-[#286b73]">{x}</span>)}</div><div className="grid gap-3 border-t border-[#e6ecef] pt-4 sm:grid-cols-2"><div><div className="tiny-label">Highest qualification</div><p className="mt-1 text-sm font-semibold text-[#40576a]">M.Sc. Atmospheric Science</p></div><div><div className="tiny-label">Experience</div><p className="mt-1 text-sm font-semibold text-[#40576a]">4 years · Forecasting operations</p></div></div></section></div><section className="rounded-xl border border-[#d6e0e7] bg-white p-5 panel-shadow"><SectionHeading title="Certificates" action={<span className="text-xs text-[#7b8b98]">2 earned</span>} /><div className="space-y-3"><Certificate title="Foundations of Forecasting" date="Issued 14 Aug 2025" onClick={() => setPreview(true)} id="forecasting" /><Certificate title="Data Quality Essentials" date="Issued 06 Jun 2025" onClick={() => setPreview(true)} id="data" /></div><div className="mt-5 rounded-lg bg-[#f1f7f7] p-4"><div className="flex gap-3"><ShieldCheck size={19} className="text-[#1e777b]" /><div><div className="text-xs font-bold text-[#345a68]">Your learning record is verified</div><p className="mt-1 text-[11px] leading-4 text-[#71838d]">Certificates issued through AptiMet are linked to your official trainee record.</p></div></div></div></section></div>{preview && <CertificateModal onClose={() => setPreview(false)} name={name} title="Foundations of Forecasting" />}</div>;
}
function Field({ label, value, editing, onChange, testId }: { label: string; value: string; editing: boolean; onChange?: (v: string) => void; testId: string }) { return <label className="block"><span className="tiny-label">{label}</span>{editing && onChange ? <input value={value} onChange={e => onChange(e.target.value)} data-testid={testId} className="mt-1 w-full border-b border-[#9fc1c6] bg-transparent py-1 text-sm font-semibold text-[#40576a] outline-none" /> : <div data-testid={testId} className="mt-1 text-sm font-semibold text-[#40576a]">{value}</div>}</label>; }
function Certificate({ title, date, onClick, id }: { title: string; date: string; onClick: () => void; id: string }) { return <button onClick={onClick} data-testid={`button-certificate-${id}`} className="flex w-full items-center gap-3 rounded-lg border border-[#dbe4e8] bg-[#fcfdfd] p-3 text-left hover:border-[#6da8ad]"><div className="grid h-12 w-12 place-items-center rounded-lg bg-[#e4f1f1] text-[#1a7178]"><Award size={23} /></div><div className="flex-1"><div className="text-xs font-bold text-[#385166]">{title}</div><div className="mt-1 text-[11px] text-[#7b8a97]">{date}</div></div><ChevronRight size={15} className="text-[#82929d]" /></button>; }
function CertificateModal({ onClose, name, title }: { onClose: () => void; name: string; title: string }) { return <div className="fixed inset-0 z-50 grid place-items-center bg-[#19364c]/40 p-5" onClick={onClose}><div onClick={e => e.stopPropagation()} className="w-full max-w-lg rounded-xl bg-white p-5 panel-shadow"><div className="flex items-center justify-between"><div className="tiny-label">Certificate preview</div><button onClick={onClose} data-testid="button-close-certificate"><X size={19} /></button></div><div className="mt-4 border-2 border-[#2a7180] bg-[#f7fbfa] p-7 text-center"><div className="mx-auto grid h-12 w-12 place-items-center rounded-full border border-[#398b91] text-[#26747d]"><Award size={25} /></div><div className="tiny-label mt-4 !text-[#3f777c]">AptiMet · Capacity Connect</div><h2 className="mt-3 text-2xl font-bold text-[#23526c]">Certificate of Completion</h2><p className="mt-5 text-xs text-[#778b94]">This certifies that</p><p className="mt-1 text-xl font-bold text-[#29495e]">{name}</p><p className="mt-5 text-xs text-[#778b94]">has successfully completed</p><p className="mt-1 text-base font-bold text-[#28727b]">{title}</p><div className="mt-7 flex justify-between border-t border-[#dce7e5] pt-4 text-left text-[10px] text-[#72858c]"><span>14 August 2025</span><span>IMD-APM-7F2K9</span></div></div><button onClick={() => alert('Print dialog opened for this certificate.')} data-testid="button-download-certificate" className="mt-4 flex w-full items-center justify-center gap-2 rounded-lg bg-[#075fa6] py-2.5 text-xs font-bold text-white"><Download size={14} /> Download certificate</button></div></div>; }

function Skills() {
  const [, setLocation] = useLocation();
  return <div className="mx-auto max-w-[1160px] p-5 md:p-8"><div className="mb-7"><div className="tiny-label mb-2">Competency map</div><h1 className="text-[28px] font-bold tracking-[-.04em] text-[#124b78]">Skill-gap assessment</h1><p className="mt-1 max-w-2xl text-sm text-[#667887]">See where your current strengths meet the Senior Forecast Analyst role — and choose the next most useful step.</p></div><div className="grid gap-5 xl:grid-cols-[1.4fr_1fr]"><section className="rounded-xl border border-[#d6e0e7] bg-white p-5 panel-shadow"><SectionHeading title="Current profile vs target role" action={<span className="rounded-full bg-[#e6f3f2] px-2.5 py-1 text-[10px] font-bold text-[#23747b]">Updated today</span>} /><div className="h-[310px]"><ResponsiveContainer width="100%" height="100%"><RadarChart data={radarData} outerRadius="72%"><PolarGrid stroke="#cddce1" /><PolarAngleAxis dataKey="skill" tick={{ fontSize: 11, fill: '#536b7a' }} /><RadarShape name="Your profile" dataKey="current" stroke="#157c7f" fill="#76c9c5" fillOpacity={.34} strokeWidth={2} /><RadarShape name="Target role" dataKey="target" stroke="#3d6f91" fill="#b6d0dc" fillOpacity={.18} strokeDasharray="5 3" /><Legend wrapperStyle={{ fontSize: 11 }} /><ChartTooltip /></RadarChart></ResponsiveContainer></div></section><section className="rounded-xl border border-[#d6e0e7] bg-white p-5 panel-shadow"><SectionHeading title="Priority gaps" /><div className="space-y-5">{[['Modelling',38,72,'Build a stronger foundation in model guidance.'],['Climatology',42,78,'Connect long-range context to daily operations.'],['Forecasting',61,88,'Sharpen confidence at decision points.']].map(([x,a,b,d]) => <div key={x as string}><div className="flex justify-between text-xs font-bold text-[#40596b]"><span>{x}</span><span className="text-[#b3763b]">{(b as number) - (a as number)} pt gap</span></div><div className="mt-2 h-2 rounded-full bg-[#edf0ef]"><div className="h-full rounded-full bg-[#d49c56]" style={{ width: `${a}%` }} /></div><p className="mt-1.5 text-[11px] leading-4 text-[#778895]">{d}</p></div>)}</div><button onClick={() => setLocation('/catalog')} data-testid="button-browse-gap-courses" className="mt-6 flex w-full items-center justify-center gap-2 rounded-lg bg-[#075fa6] py-2.5 text-xs font-bold text-white">Browse gap-closing courses <ArrowRight size={14} /></button></section></div><section className="mt-6"><SectionHeading eyebrow="Curated next steps" title="Recommended to close your gaps" /><div className="grid gap-4 md:grid-cols-3">{[courses[1], courses[2], courses[5]].map(c => <button onClick={() => setLocation(`/courses/${c.id}`)} key={c.id} data-testid={`button-skill-course-${c.id}`} className="rounded-xl border border-[#d6e0e7] bg-white p-4 text-left panel-shadow hover:-translate-y-0.5"><div className="flex items-center justify-between"><div className="grid h-10 w-10 place-items-center rounded-lg bg-[#e2f0f1] text-[#1b7479]"><BookOpen size={19} /></div><span className="text-[10px] font-bold text-[#738590]">{c.duration}</span></div><h3 className="mt-4 text-sm font-bold text-[#29465a]">{c.title}</h3><p className="mt-1 text-xs leading-5 text-[#718390]">{c.description}</p><div className="mt-4 flex items-center gap-1 text-[11px] font-bold text-[#26727a]">Close modelling gap <ArrowRight size={13} /></div></button>)}</div></section></div>;
}

function WarRoom() {
  const [step, setStep] = useState(0); const [choice, setChoice] = useState<string | null>(null); const [finished, setFinished] = useState(false); const [, setLocation] = useLocation();
  const events = [{ title: 'Cyclone system detected', detail: 'A deep depression has formed in the Bay of Bengal.', choices: ['Monitor and await another advisory','Issue preliminary coastal watch','Escalate to district coordination'] }, { title: 'Landfall ETA updated', detail: 'The system is tracking west-northwest. Landfall window narrowed to 18 hours.', choices: ['Issue coastal warning now','Hold until next model run','Brief only the coastal districts'] }, { title: 'Rainfall risk increasing', detail: 'Ensemble guidance shows 240mm+ rainfall over two districts.', choices: ['Open relief coordination channel','Publish rainfall advisory','Wait for observed totals'] }];
  if (finished) return <div className="min-h-[calc(100dvh-70px)] bg-[#102c43] p-5 text-white md:p-10"><div className="mx-auto max-w-3xl"><div className="tiny-label !text-[#88c8c9]">Simulation complete</div><h1 className="mt-3 text-4xl font-bold tracking-[-.04em]">Cyclone War Room scorecard</h1><div className="mt-8 grid gap-4 sm:grid-cols-3"><div className="rounded-xl border border-[#2b5265] bg-[#173b52] p-5"><div className="tiny-label !text-[#88c8c9]">Overall score</div><div className="mt-2 text-4xl font-bold text-[#9ce1d9]">78<span className="text-xl">/100</span></div></div><div className="rounded-xl border border-[#2b5265] bg-[#173b52] p-5"><div className="tiny-label !text-[#88c8c9]">Decisions</div><div className="mt-2 text-2xl font-bold">3 of 3</div></div><div className="rounded-xl border border-[#2b5265] bg-[#173b52] p-5"><div className="tiny-label !text-[#88c8c9]">Standout</div><div className="mt-2 text-sm font-bold">Early escalation</div></div></div><div className="mt-6 rounded-xl border border-[#2b5265] bg-[#173b52] p-6"><h2 className="text-lg font-bold">Expert feedback</h2><p className="mt-3 text-sm leading-6 text-[#bad0d5]">You identified the need for an early coastal warning and kept the coordination loop moving. Build deeper confidence in rainfall impact thresholds with the recommended Climate Risk pathway.</p><button onClick={() => setLocation('/skills')} data-testid="button-warroom-skills" className="mt-6 rounded-lg bg-[#85d6d1] px-4 py-2.5 text-xs font-bold text-[#143f50]">Review skill gaps</button></div></div></div>;
  const current = events[step];
  return <div className="min-h-[calc(100dvh-70px)] bg-[#102c43] p-5 text-white md:p-8"><div className="mx-auto max-w-[1180px]"><div className="flex flex-wrap items-center justify-between gap-4"><div><Link href="/" data-testid="link-exit-warroom" className="mb-3 inline-flex items-center gap-2 text-xs font-bold text-[#94c8cc]"><ArrowLeft size={14} /> Exit simulation</Link><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#d85f4e]"><Activity size={21} /></div><div><div className="tiny-label !text-[#94c8cc]">Live assessment</div><h1 className="text-2xl font-bold">Cyclone War Room</h1></div></div></div><div className="rounded-lg border border-[#34566a] bg-[#173b52] px-4 py-2 text-right"><div className="tiny-label !text-[#94c8cc]">Scenario time</div><div className="font-mono text-lg font-bold text-[#9ce1d9]">T+{step * 30} min</div></div></div><div className="mt-7 grid gap-5 lg:grid-cols-[1.3fr_.7fr]"><div className="relative min-h-[380px] overflow-hidden rounded-xl border border-[#315269] bg-[#173d56]"><div className="absolute inset-0 opacity-35" style={{ backgroundImage: 'linear-gradient(#6aa7ab 1px, transparent 1px), linear-gradient(90deg,#6aa7ab 1px, transparent 1px)', backgroundSize: '42px 42px' }} /><div className="absolute left-[22%] top-[24%] h-44 w-56 rotate-12 rounded-[45%] bg-[#2f7480]/60 blur-[1px]" /><div className="absolute left-[45%] top-[35%] h-4 w-4 rounded-full bg-[#ef9c61] shadow-[0_0_0_10px_rgba(239,156,97,.18)]" /><div className="absolute bottom-6 left-6 text-xs text-[#9cc4c6]"><Map size={16} className="mr-2 inline" />Bay of Bengal · Operational map view</div></div><div className="rounded-xl border border-[#315269] bg-[#173b52] p-5"><div className="tiny-label !text-[#94c8cc]">Decision point {step + 1} of {events.length}</div><h2 className="mt-3 text-xl font-bold">{current.title}</h2><p className="mt-2 text-sm leading-6 text-[#b8ced2]">{current.detail}</p><div className="mt-6 space-y-2">{current.choices.map((x, i) => <button onClick={() => { setChoice(x); setTimeout(() => { if (step === events.length - 1) setFinished(true); else { setStep(step + 1); setChoice(null); } }, 250); }} key={x} data-testid={`button-warroom-choice-${i}`} className={`w-full rounded-lg border px-3 py-3 text-left text-xs font-semibold transition-colors ${choice === x ? 'border-[#85d6d1] bg-[#285d69] text-white' : 'border-[#416273] text-[#d0e0e2] hover:border-[#85d6d1] hover:bg-[#214c5c]'}`}>{x}<ChevronRight size={14} className="float-right" /></button>)}</div><div className="mt-6 h-1.5 rounded-full bg-[#2d5365]"><div className="h-full rounded-full bg-[#84d5d1]" style={{ width: `${((step + 1) / events.length) * 100}%` }} /></div></div></div></div></div>;
}

function ForecastDuel() {
  const [rain, setRain] = useState('120–160 mm'); const [severity, setSeverity] = useState('Severe'); const [submitted, setSubmitted] = useState(false); const { toast } = useToast();
  return <div className="mx-auto max-w-[1050px] p-5 md:p-8"><div className="mb-7"><div className="tiny-label mb-2">Historical assessment</div><h1 className="text-[28px] font-bold tracking-[-.04em] text-[#124b78]">Forecast Duel</h1><p className="mt-1 text-sm text-[#667887]">Make the call with only the information available at the time.</p></div><div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><section className="rounded-xl border border-[#d6e0e7] bg-white p-5 panel-shadow"><div className="flex items-center justify-between"><div><div className="tiny-label">Case file 04 · 12 June 2021</div><h2 className="mt-1 text-lg font-bold text-[#294359]">Konkan monsoon pulse</h2></div><div className="rounded-lg bg-[#e7f1f5] p-2 text-[#28708a]"><Gauge size={21} /></div></div><div className="mt-5 h-28 rounded-lg bg-[#e6f0f1] p-4"><div className="flex h-full items-end gap-2">{[35,46,38,62,52,76,67,88,70,94,83,100].map((x, i) => <div key={i} className="flex-1 rounded-t bg-[#5ba2a2]" style={{ height: `${x}%` }} />)}</div></div><p className="mt-4 text-xs leading-5 text-[#6a7d8b]">Observed rainfall and model guidance through 12:00 IST. Submit your forecast for the following 24 hours.</p><div className="mt-6 grid gap-4 sm:grid-cols-2"><label><span className="tiny-label">Predicted rainfall</span><select value={rain} onChange={e => setRain(e.target.value)} data-testid="select-rainfall" className="mt-2 w-full rounded-lg border border-[#d6e0e6] bg-white px-3 py-2.5 text-sm font-semibold text-[#405a6a]"><option>60–100 mm</option><option>120–160 mm</option><option>160–240 mm</option><option>240+ mm</option></select></label><label><span className="tiny-label">Cyclone severity</span><select value={severity} onChange={e => setSeverity(e.target.value)} data-testid="select-severity" className="mt-2 w-full rounded-lg border border-[#d6e0e6] bg-white px-3 py-2.5 text-sm font-semibold text-[#405a6a]"><option>Moderate</option><option>Severe</option><option>Very severe</option></select></label></div><button onClick={() => { setSubmitted(true); toast({ title: 'Forecast submitted', description: 'Your call has been locked for this case.' }); }} data-testid="button-submit-forecast" className="mt-6 rounded-lg bg-[#075fa6] px-5 py-2.5 text-xs font-bold text-white">{submitted ? 'Forecast locked' : 'Submit forecast'}</button></section>{submitted ? <section className="rounded-xl border border-[#c8dfe0] bg-[#eef8f7] p-5 panel-shadow"><div className="tiny-label !text-[#28757b]">Results revealed</div><h2 className="mt-1 text-lg font-bold text-[#294359]">Your call vs the record</h2><div className="mt-5 grid gap-3"><div className="rounded-lg bg-white p-4"><div className="text-[10px] font-bold uppercase text-[#78909a]">Your forecast</div><div className="mt-1 text-xl font-bold text-[#28747b]">{rain}</div><div className="mt-1 text-xs text-[#738691]">{severity} system</div></div><div className="rounded-lg bg-white p-4"><div className="text-[10px] font-bold uppercase text-[#78909a]">Observed outcome</div><div className="mt-1 text-xl font-bold text-[#355773]">160–240 mm</div><div className="mt-1 text-xs text-[#738691]">Very severe rainfall episode</div></div><div className="mt-2 flex items-center justify-between border-t border-[#cfe2e1] pt-4"><span className="text-sm font-bold text-[#48636d]">Accuracy score</span><span className="text-2xl font-bold text-[#28747b]">84 / 100</span></div></div><p className="mt-4 text-xs leading-5 text-[#55727a]">Strong range selection. Your severity call was directionally right; review the impact-threshold module to calibrate the upper tail.</p></section> : <section className="rounded-xl border border-[#d6e0e7] bg-white p-5 panel-shadow"><SectionHeading title="How it works" /><div className="space-y-4">{[['01','Read the snapshot','Use only the data available before the cutoff.'],['02','Make your call','Choose a rainfall range and system severity.'],['03','Compare the record','See the official IMD forecast and outcome side by side.']].map(([n,a,b]) => <div className="flex gap-3" key={n}><div className="font-mono text-xs font-bold text-[#3a8b91]">{n}</div><div><div className="text-sm font-bold text-[#405a6c]">{a}</div><p className="mt-1 text-xs leading-5 text-[#7a8b96]">{b}</p></div></div>)}</div></section>}</div></div>;
}

function Quiz() {
  const { id } = useParams<{ id: string }>(); const course = courses.find(c => c.id === id) ?? courses[0]; const [, setLocation] = useLocation();
  const questions = [
    { q: 'Which signal most directly indicates a strengthening pressure gradient?', options: ['Widening isobars','Tightly packed isobars','A clear sky window','A stable dew point'], answer: 1, tag: 'Synoptic reading' },
    { q: 'When model guidance diverges, the strongest briefing should first communicate:', options: ['A single confident outcome','The uncertainty range and what drives it','Only the previous run','No forecast at all'], answer: 1, tag: 'Communication' },
    { q: 'A quality check on an observation archive should identify:', options: ['Missing and physically implausible values','The most colourful chart','Only the maximum value','The oldest station'], answer: 0, tag: 'Data quality' },
    { q: 'The best operational next step after a threshold is crossed is to:', options: ['Wait for perfect certainty','Document the trigger and coordinate action','Delete the previous forecast','Change the threshold'], answer: 1, tag: 'Decision practice' },
  ];
  const [index, setIndex] = useState(0); const [answers, setAnswers] = useState<number[]>([]); const [result, setResult] = useState(false);
  const current = questions[index]; const score = answers.reduce((sum, a, i) => sum + (a === questions[i].answer ? 1 : 0), 0);
  if (result) return <div className="mx-auto max-w-3xl p-5 md:p-10"><Link href={`/courses/${course.id}`} data-testid="link-back-result" className="inline-flex items-center gap-2 text-xs font-bold text-[#557284]"><ArrowLeft size={14} /> Return to course</Link><div className="mt-6 rounded-xl border border-[#d6e0e7] bg-white p-7 text-center panel-shadow"><div className="mx-auto grid h-16 w-16 place-items-center rounded-full bg-[#e0f2ef] text-[#167775]"><Award size={30} /></div><div className="tiny-label mt-5">Assessment complete</div><h1 className="mt-2 text-3xl font-bold text-[#24465c]">{score >= 3 ? 'Strong operational grasp' : 'Keep building your foundation'}</h1><div className="mx-auto mt-6 flex max-w-sm items-center justify-center gap-10"><div><div className="text-4xl font-bold text-[#167577]">{score * 25}</div><div className="tiny-label mt-1">Score</div></div><div className="h-10 border-l border-[#d9e4e8]" /><div><div className={`text-sm font-bold ${score >= 3 ? 'text-[#28786e]' : 'text-[#af6c3d]'}`}>{score >= 3 ? 'Passed' : 'Review recommended'}</div><div className="tiny-label mt-1">Outcome</div></div></div><div className="mt-7 rounded-lg bg-[#f2f7f7] p-4 text-left"><div className="text-xs font-bold text-[#385a67]">Explainable feedback</div><p className="mt-2 text-xs leading-5 text-[#6c8089]">{score >= 3 ? 'Your answers show a solid understanding of the decision framework. Keep practising how to communicate uncertainty under time pressure.' : 'Revisit the data quality and synoptic reading materials, then retry the assessment to reinforce the concepts.'}</p></div><div className="mt-6 flex justify-center gap-3"><button onClick={() => { setIndex(0); setAnswers([]); setResult(false); }} data-testid="button-retry-quiz" className="rounded-lg border border-[#6aa9ad] px-4 py-2.5 text-xs font-bold text-[#247078]">Retry assessment</button>{score >= 3 && <button onClick={() => alert('Certificate preview is available from your profile.')} data-testid="button-view-quiz-certificate" className="rounded-lg bg-[#075fa6] px-4 py-2.5 text-xs font-bold text-white">View certificate</button>}</div></div></div>;
  const choose = (option: number) => setAnswers([...answers.slice(0, index), option]);
  return <div className="mx-auto max-w-3xl p-5 md:p-10"><div className="flex items-center justify-between"><Link href={`/courses/${course.id}`} data-testid="link-exit-quiz" className="inline-flex items-center gap-2 text-xs font-bold text-[#557284]"><ArrowLeft size={14} /> Exit assessment</Link><span className="font-mono text-xs font-bold text-[#6d818f]">20:00</span></div><div className="mt-7"><div className="flex items-center justify-between"><div className="tiny-label">Question {index + 1} of {questions.length}</div><div className="text-xs font-bold text-[#31787e]">{course.title}</div></div><div className="mt-2 h-1.5 rounded-full bg-[#e0e8eb]"><div className="h-full rounded-full bg-[#177b80]" style={{ width: `${((index + 1) / questions.length) * 100}%` }} /></div><div className="mt-6 rounded-xl border border-[#d6e0e7] bg-white p-6 panel-shadow md:p-8"><div className="rounded bg-[#e7f3f3] px-2 py-1 text-[10px] font-bold uppercase tracking-wider text-[#28747a]">{current.tag}</div><h1 className="mt-5 text-xl font-bold leading-7 text-[#29465b]">{current.q}</h1><div className="mt-6 space-y-3">{current.options.map((option, i) => <button onClick={() => choose(i)} key={option} data-testid={`button-answer-${i}`} className={`flex w-full items-center gap-3 rounded-lg border p-3.5 text-left text-sm font-semibold ${answers[index] === i ? 'border-[#187d81] bg-[#eaf7f5] text-[#1d656d]' : 'border-[#dce5e9] text-[#536a79] hover:border-[#74aeb1]'}`}><span className="grid h-6 w-6 place-items-center rounded-full border border-current text-[11px]">{String.fromCharCode(65 + i)}</span>{option}</button>)}</div><div className="mt-7 flex justify-between"><button onClick={() => setIndex(Math.max(0, index - 1))} disabled={index === 0} data-testid="button-previous-question" className="flex items-center gap-2 rounded-lg border border-[#d6e1e6] px-4 py-2.5 text-xs font-bold text-[#607585] disabled:opacity-40"><ArrowLeft size={14} /> Previous</button><button onClick={() => index === questions.length - 1 ? setResult(true) : setIndex(index + 1)} disabled={answers[index] === undefined} data-testid="button-next-question" className="flex items-center gap-2 rounded-lg bg-[#075fa6] px-4 py-2.5 text-xs font-bold text-white disabled:bg-[#b9c8d0]">{index === questions.length - 1 ? 'Submit assessment' : 'Next question'} <ArrowRight size={14} /></button></div></div></div></div>;
}

function NotFound() { return <div className="p-12 text-center"><h1 className="text-2xl font-bold">Page not found</h1><Link href="/" data-testid="link-return-home" className="mt-4 inline-block text-sm font-bold text-[#166d80]">Return to dashboard</Link></div>; }
function Router() { return <Shell><ErrorBoundary><Switch><Route path="/" component={Dashboard} /><Route path="/catalog" component={Catalog} /><Route path="/courses/:id/assessment" component={Quiz} /><Route path="/courses/:id" component={CourseDetail} /><Route path="/profile" component={Profile} /><Route path="/skills" component={Skills} /><Route path="/war-room" component={WarRoom} /><Route path="/forecast-duel" component={ForecastDuel} /><Route component={NotFound} /></Switch></ErrorBoundary></Shell>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;